export const oralPrompt='Retell the story in your own words.';
export const oralQuestion='What choices does Jimmy have? Why does he make such a decision?';
export const oralQuestionDirections='Answer the following questions and record your answer.';
export const oralStory='After many years away, Daniel returned to the small town where he had grown up. He planned to meet his oldest friend, Peter, outside their former school. Daniel had become a successful merchant, while Peter had stayed in the town and worked as a teacher. They had promised to meet on the same day twenty years after leaving school. When they finally met, each thought that the other had found a better life. Their conversation helped them understand that friendship and kindness mattered more than money or fame. They walked through the streets together and agreed to keep in touch. Before Daniel left, Peter gave him an old photograph of their class. Daniel realized that the photograph and his friendship were more precious than his expensive possessions.';
export const oralRetelling='Daniel returned to his home town after a long time away. He wanted to meet Peter, an old school friend. Twenty years earlier, they had promised to meet again outside their school. Daniel had become a merchant, and Peter was now a teacher. At first, both men believed that the other had been more successful. However, as they talked and walked around the town, they realized that money and fame were less important than friendship. Peter gave Daniel a photograph of their old class. Daniel treasured it and understood that their lasting friendship was worth more than his possessions. They decided to stay in touch.';

export function oralTestWave(seconds=1,{silent=false}={}){
  const samples=Math.round(22050*seconds),bytes=Buffer.alloc(44+samples*2);bytes.write('RIFF');bytes.writeUInt32LE(bytes.length-8,4);bytes.write('WAVEfmt ',8);bytes.writeUInt32LE(16,16);bytes.writeUInt16LE(1,20);bytes.writeUInt16LE(1,22);bytes.writeUInt32LE(22050,24);bytes.writeUInt32LE(44100,28);bytes.writeUInt16LE(2,32);bytes.writeUInt16LE(16,34);bytes.write('data',36);bytes.writeUInt32LE(samples*2,40);for(let i=0;!silent&&i<samples;i++)bytes.writeInt16LE(Math.round(Math.sin(i*2*Math.PI*440/22050)*5000),44+i*2);return bytes;
}

export function oralRetellHTML({legacy=false,replayData=false,replayUnavailable=false,saveDelay=0,uploadFailure=false,verifyCapture=false,context=true,saved=false,mixed=false,followup=false,progress=50,prompt=oralPrompt,directions='Complete the following task and record your answer.'}={}){
  return `<!doctype html><html><body><div class="pc-break-crumb"><span class="pc-break-crumb-text">Offline book</span><span class="pc-break-crumb-text">Offline unit</span><span class="pc-break-crumb-text">Getting the idea</span></div><div class="pc-header-tab-activity">Getting the idea</div><div class="pc-task pc-header-task-activity">Exercise 2</div>
  <main class="pc-main-container"><div class="layout-container"><div class="layout-progress-container"><div class="comp-question-progress" style="width:100%"><div class="percent" style="width:${progress}%"></div></div></div><div class="abs-direction">${directions}</div>${context?'<div class="layout-material-container">'+oralStory+'</div>':''}${mixed?'<textarea></textarea>':''}<div class="p-oral-personal-state"><div class="oral-personal-state-sentence-container"><span class="p-oral-personal-state-score_layout"><span class="score_layout">0</span></span><div class="component-htmlview"><p>${prompt}</p></div></div><div class="oral-personal-state__reply"><div class="record-button-group"><div class="record-count-down">03:00</div><div class="ucomp-recorder"><span class="record-icon button-record"><svg><path d="M340,450 L450,500"/></svg></span></div><span class="record-tips">点击按钮，结束录音</span></div></div></div></div></main><footer class="question-common-course-page"><a class="btn">下一题</a></footer>
  <script>
  window.originalModern=navigator.mediaDevices.getUserMedia;window.originalLegacy=navigator.webkitGetUserMedia;
  const legacyInput=navigator.webkitGetUserMedia.bind(navigator),input=${legacy?'constraints=>new Promise((resolve,reject)=>legacyInput(constraints,resolve,reject))':'navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices)'};
  const cachedInput=input;let record=document.querySelector('.button-record'),recorder,stream,chunks=[];window.recording=false;window.footerClicks=0;window.replayClicks=0;window.replayFetches=0;window.uploadReady=${saved};window.footerDuringUpload=false;window.recordStarts=[];window.recordedUploads=[];
  window.fetch=async()=>{window.replayFetches++;throw new Error('replay must not be fetched');};
  window.bindRecorder=()=>{record=document.querySelector('.button-record');record.onclick=async()=>{if(window.recording){window.recording=false;record.querySelector('path').setAttribute('d','M340,450 L450,500');recorder.stop();return;}
    try{stream=await cachedInput({audio:true});document.querySelectorAll('.audio-replay,audio').forEach(el=>el.remove());if(!document.querySelector('.record-count-down')){const clock=document.createElement('div');clock.className='record-count-down';clock.textContent='03:00';document.querySelector('.record-button-group').prepend(clock);}chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=event=>chunks.push(event.data);recorder.onstop=async()=>{
      const audio=document.createElement('audio'),blob=new Blob(chunks,{type:recorder.mimeType});audio.preload=${JSON.stringify(replayUnavailable?'none':'metadata')};audio.src=${replayUnavailable?JSON.stringify('https://recordings.example.test/uploaded-recording.webm'):replayData?'await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(blob);})':'URL.createObjectURL(blob)'};document.querySelector('.oral-personal-state__reply').append(audio);window.savedAudio=audio;
      const replay=document.createElement('button');replay.className='audio-replay';replay.textContent='回放';replay.onclick=()=>{window.replayClicks++;return audio.play();};document.querySelector('.record-button-group').append(replay);document.querySelector('.record-count-down')?.remove();window.recordingSaved=true;for(const track of stream.getTracks())track.stop();
      const uploading=document.createElement('span');uploading.dataset.uploading='true';uploading.textContent='录音上传中';document.querySelector('.oral-personal-state__reply').append(uploading);
      if(${verifyCapture}){const probe=new AudioContext();try{const decoded=await probe.decodeAudioData(await blob.arrayBuffer());let energy=0;const samples=decoded.getChannelData(0);for(const sample of samples)energy+=sample*sample;window.recordedUploads.push({page:window.questionIndex||0,seconds:decoded.duration,rms:Math.sqrt(energy/samples.length)});}finally{await probe.close();}}
      if(${uploadFailure}){const error=document.createElement('div');error.setAttribute('role','alert');error.textContent='录音上传失败，请重试';document.querySelector('.oral-personal-state__reply').append(error);return;}
      await new Promise(resolve=>setTimeout(resolve,${saveDelay}));uploading.remove();window.uploadReady=true;
    };recorder.start();window.recordStarts.push(window.questionIndex||0);window.recording=true;record.querySelector('path').setAttribute('d','M645.744434,351 L378,351 L351,673 Z');}catch(error){window.recordingError=error.name;}};};window.bindRecorder();
  document.querySelector('footer a').onclick=()=>{window.footerClicks++;window.footerDuringUpload ||= !window.uploadReady;document.querySelector('main').innerHTML=${JSON.stringify(followup?'<div class="question-item"><h3>Explain the ending of the story.</h3><textarea></textarea></div>':'<h2>答题小结</h2><p>共1道题，主观题1道</p><p>主观题 已作答 (1/1) 未作答 (0/1)</p>')};document.querySelector('footer a').textContent=${JSON.stringify(followup?'提交':'继续学习')};};
  ${saved?'document.querySelector(".record-count-down").remove();const audio=document.createElement("audio");audio.src="data:audio/wav;base64,'+oralTestWave(1.8).toString('base64')+'";document.querySelector(".oral-personal-state__reply").append(audio);const replay=document.createElement("button");replay.className="audio-replay";replay.textContent="回放";document.querySelector(".record-button-group").append(replay);':''}
  </script></body></html>`;
}

/** An in-document question index intentionally resets if the page is reloaded. */
export function oralSequenceHTML({count=3,savedPages=[],legacy=false,boundary=false,prompts=[],directions=[]}={}){
  const html=oralRetellHTML({legacy,context:false,progress:100/count,saved:savedPages.includes(0),verifyCapture:true,prompt:prompts[0]||oralPrompt,directions:directions[0]||'Complete the following task and record your answer.'});
  const script=`<script>
    const template=document.querySelector('main').innerHTML,savedPages=${JSON.stringify(savedPages)},prompts=${JSON.stringify(prompts)},directions=${JSON.stringify(directions)};window.questionIndex=0;window.sequenceDone=false;
    function renderQuestion(){
      document.querySelector('main').innerHTML=template;document.querySelectorAll('main audio,main .audio-replay,main [data-uploading]').forEach(el=>el.remove());
      document.querySelector('.percent').style.width=((window.questionIndex+1)/${count}*100)+'%';
      document.querySelector('.oral-personal-state-sentence-container .component-htmlview p').textContent=prompts[window.questionIndex]||${JSON.stringify(oralPrompt)};
      document.querySelector('.abs-direction').textContent=directions[window.questionIndex]||'Complete the following task and record your answer.';
      const group=document.querySelector('.record-button-group');if(!group.querySelector('.record-count-down')){const clock=document.createElement('div');clock.className='record-count-down';clock.textContent='03:00';group.prepend(clock);}
      window.recordingSaved=false;window.uploadReady=savedPages.includes(window.questionIndex);window.bindRecorder();
      if(window.uploadReady){document.querySelector('.record-count-down').remove();const audio=document.createElement('audio');audio.src='data:audio/wav;base64,${oralTestWave(1.8).toString('base64')}';document.querySelector('.oral-personal-state__reply').append(audio);const replay=document.createElement('button');replay.className='audio-replay';replay.textContent='回放';replay.onclick=()=>{window.replayClicks++;return audio.play();};group.append(replay);}
      document.querySelector('footer a').textContent=window.questionIndex===${count}-1?'提交':'下一题';
    }
    document.querySelector('footer a').onclick=()=>{
      window.footerClicks++;window.footerDuringUpload ||= !window.uploadReady;
      if(window.questionIndex===${count}-1){window.sequenceDone=true;document.querySelector('main').innerHTML='<h2>答题小结</h2><p>共${count}道题，主观题${count}道</p><p>主观题 已作答 (${count}/${count}) 未作答 (0/${count})</p>';document.querySelector('footer a').textContent='继续学习';return;}
      window.questionIndex++;renderQuestion();if(${boundary})document.querySelector('.pc-header-task-activity').textContent='Exercise 3';
    };renderQuestion();
  </script>`;
  return html.replace('</body>',script+'</body>');
}
